"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["48939"],{92274(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.formulario_portavel.operacao_de_agregado_invalida","status":422,"titulo":"A opera\xe7\xe3o do agregado \xe9 EXISTE ou VALORES_PRESENTES"},"descricao":{"codigo":"uniplus.formulario_portavel.operacao_de_agregado_invalida","requisitos":[],"oQueAconteceu":["A avalia\xe7\xe3o de um formul\xe1rio sem cadastro confere as regras de um formul\xe1rio apresentado contra respostas simuladas, sem gravar nada nem registrar o conte\xfado enviado. Um resumo sobre um grupo repet\xedvel, como \\"existe membro que...\\" ou \\"categorias presentes na lista\\", traz uma `operacao` que n\xe3o \xe9 `EXISTE` nem `VALORES_PRESENTES`, inclusive o texto vazio. A mensagem identifica o c\xf3digo `{c\xf3digo\\\\}` e informa as opera\xe7\xf5es aceitas, e o `field` \xe9 o caminho do resumo seguido de `.operacao`, como `agregados[0].operacao`.","A recusa vem na lista `errors` da resposta, uma entrada por recusa, cada uma com `field` igual ao caminho do elemento recusado nas regras enviadas, ou mais fundo quando a recusa \xe9 de uma parte dele. As regras recebidas s\xe3o lidas por inteiro antes da avalia\xe7\xe3o, nesta ordem: as p\xe1ginas (com os itens e os grupos de cada uma), os termos, as deriva\xe7\xf5es, os resumos de grupo e, por fim, o conjunto, e todas as recusas de uma mesma etapa voltam juntas. Havendo defeito de estrutura do documento (elemento nulo numa lista ou grupo sem `ocorrencias`), s\xf3 as recusas de estrutura voltam e a opera\xe7\xe3o do resumo n\xe3o \xe9 conferida nessa resposta. A confer\xeancia do conjunto s\xf3 vem depois que nenhum elemento foi recusado, e \xe9 a \xfanica recusa sem `field`.","As propriedades de texto que o corpo n\xe3o pode omitir, como o c\xf3digo, a obrigatoriedade e a opera\xe7\xe3o, ausentes ou nulas, s\xe3o recusadas antes, com 400 e sem c\xf3digo deste cat\xe1logo, pela leitura do corpo."],"comoResolver":["Informe `EXISTE` ou `VALORES_PRESENTES` na `operacao` do resumo de grupo e repita a avalia\xe7\xe3o."],"ondeAparece":["Avalia\xe7\xe3o de formul\xe1rio sem cadastro"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Formulario portavel"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);